function filterModels(models, filter) {
  return models.filter((m) => {
    if (filter?.kind && (m.kind ?? "chat") !== filter.kind) return false;
    if (filter?.capability && !(m.capabilities?.mediaCapabilities ?? []).includes(filter.capability)) {
      return false;
    }
    return true;
  });
}
function modelMatchesCapability(model, cap) {
  const c = model.capabilities ?? {};
  const mc = c.mediaCapabilities ?? [];
  switch (cap) {
    case "tools":
      return c.tools === true;
    case "structured-output":
      return c.tools === true;
    case "vision":
      return c.vision === true;
    case "reasoning":
      return c.reasoning === true;
    case "long-context":
      return (c.contextWindow ?? 0) >= 2e5;
    case "streaming":
      return c.streaming === true || c.streamingMedia === true;
    case "image-generation":
      return mc.includes("text-to-image");
    case "image-edit":
      return mc.includes("image-to-image") || mc.includes("image-edit") || mc.includes("remove-background");
    case "inpaint":
      return mc.includes("inpaint");
    case "outpaint":
      return mc.includes("outpaint");
    case "upscale":
      return mc.includes("upscale");
    case "video-generation":
      return mc.includes("text-to-video") || mc.includes("image-to-video");
    case "video-edit":
      return mc.includes("video-to-video") || mc.includes("video-edit");
    case "tts":
      return mc.includes("text-to-speech");
    case "stt":
      return mc.includes("speech-to-text");
    case "voice-clone":
      return mc.includes("voice-clone");
    case "music-gen":
      return mc.includes("music-gen");
    case "web-search":
      return mc.includes("web-search");
    case "deep-research":
      return mc.includes("deep-research");
    default:
      return false;
  }
}
