function resolveProvider(providerId, providers = DEFAULT_PROVIDERS) {
  const match = providers.find((p) => p.id === providerId);
  if (match) return match;
  return providers.find((p) => p.id === "other") ?? {
    id: "other",
    name: providerId,
    color: "#999999",
    glyph: providerId.charAt(0).toUpperCase()
  };
}
